Object.assign(SNIP,{});PRESET_NOTES["l70"]={"Ví dụ: Kích thước cây con": "Lá có sz = 1. Đỉnh 5 có hai lá con nên sz[5] = 3; đỉnh 2 = 1 + sz[4] + sz[5] = 5; gốc chứa cả 9 đỉnh.", "Ví dụ: Bữa tiệc công ty": "Tối ưu 27: mời 2, 7, 8, 3, 9 (5 + 7 + 3 + 4 + 8) và không mời giám đốc. 7, 8 được đi cùng 2 vì sếp trực tiếp của họ là 5; 3 và 9 cũng không phải sếp – nhân viên trực tiếp (6 ở giữa).", "Ví dụ: Đường kính cây": "Đường đi dài nhất 7 – 5 – 2 – 1 – 3 – 6 – 9 có 6 cạnh, gập tại gốc 1 (nhánh 3 cạnh xuống 7 và nhánh 3 cạnh xuống 9). Mọi đường đi đơn trên cây đều “gập” tại đỉnh cao nhất của nó.", "Ví dụ: Đổi gốc — tổng khoảng cách": "Hai lượt duyệt: ngược BFS để tính sz (từ lá lên), xuôi BFS để đổi gốc (từ gốc xuống). Tổng O(n) thay vì chạy BFS từ từng đỉnh O(n²).", "Lỗi: đệ quy quá sâu trên cây dạng đường thẳng": "Mỗi lời gọi chiếm một khung trên ngăn xếp; một triệu lời gọi lồng nhau vượt ngăn xếp mặc định (vài MB). Trình mô phỏng dừng ở độ sâu 3000; trên máy thật chương trình thường bị stack overflow (trình biên dịch tối ưu đôi khi tự đổi đệ quy kiểu này thành vòng lặp, nhưng không thể trông chờ điều đó). Với cây lớn, dùng thứ tự BFS ngược như các ví dụ trên."};EX_HINTS["l70"]=[["moi[v] = tổng lớn nhất trong cây con của v khi mời v; khong[v] = khi không mời v.", "moi[v] = w[v] + Σ khong[con]; khong[v] = Σ max(moi[con], khong[con]).", "Vì p_i < i, duyệt v từ n về 1: khi tới v, mọi con của v (số hiệu lớn hơn) đã xong. Đẩy kết quả của v lên p[v] ngay. Tổng tới 2·10^14: long long."], ["Gốc 1. xuong[v] = đường đi dài nhất từ v đi xuống cây con của nó. Đường đi dài nhất “gập” tại v = tổng hai nhánh xuống dài nhất qua hai con khác nhau.", "Duyệt ngược thứ tự BFS để con được tính trước cha (không đệ quy). Giữ hai giá trị lớn nhất a ≥ b.", "Cách khác: BFS từ 1 tìm đỉnh xa nhất x, rồi BFS từ x — khoảng cách xa nhất là đường kính (chỉ đúng khi trọng số không âm)."], ["Gốc 1: kq[1] = tổng độ sâu mọi đỉnh. sz[v] = số đỉnh trong cây con của v (duyệt ngược BFS).", "Dời gốc từ cha sang con c: sz[c] đỉnh gần thêm 1, n − sz[c] đỉnh còn lại xa thêm 1: kq[c] = kq[cha] − sz[c] + (n − sz[c]). Duyệt xuôi BFS.", "BFS từ từng đỉnh tốn O(n²). Tổng tới n²/2 ≈ 2·10^10: long long."]];
