const PR70=[{label:"Ví dụ: Kích thước cây con",input:"9\n1 2\n1 3\n2 4\n2 5\n3 6\n5 7\n5 8\n6 9\n",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n;\nvector<vector<int>> adj;\n\nvoid docCay() {\n    cin >> n;\n    adj.resize(n + 1);\n    for (int i = 0; i < n - 1; i++) {\n        int a, b;\n        cin >> a >> b;\n        adj[a].push_back(b);\n        adj[b].push_back(a);\n    }\n}\n\nvector<int> sz;\n\nvoid dfs(int v, int p) {\n    sz[v] = 1;\n    for (int c : adj[v])\n        if (c != p) {\n            dfs(c, v);                 // tính xong cây con của c\n            sz[v] += sz[c];            // rồi gộp vào v\n        }\n}\n\nint main() {\n    docCay();\n    sz.assign(n + 1, 0);\n    dfs(1, 0);\n    for (int v = 1; v <= n; v++) cout << sz[v] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",base:1,xy:[[0.5,0],[0.25,0.33],[0.75,0.33],[0.08,0.66],[0.4,0.66],[0.75,0.66],[0.28,1],[0.52,1],[0.75,1]],adj:"adj",lab:"sz",cur:["v","c"]},{type:"calls"}],py:{code:"def dfs(v, p):\n    sz[v] = 1\n    for c in adj[v]:\n        if c != p:\n            dfs(c, v)                  # tính xong cây con của c\n            sz[v] += sz[c]             # rồi gộp vào v\n\nn = int(input())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(n - 1):\n    a, b = map(int, input().split())\n    adj[a].append(b)\n    adj[b].append(a)\nsz = [0] * (n + 1)\ndfs(1, 0)\nprint(*sz[1:])"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static int n;\n    static List<int>[] adj;\n\n    static void DocCay()\n    {\n        n = int.Parse(Console.ReadLine());\n        adj = new List<int>[n + 1];\n        for (int i = 0; i <= n; i++) adj[i] = new List<int>();\n        for (int i = 0; i < n - 1; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            adj[e[1]].Add(e[0]);\n        }\n    }\n\n    static int[] sz;\n\n    static void Dfs(int v, int p)\n    {\n        sz[v] = 1;\n        foreach (int c in adj[v])\n            if (c != p)\n            {\n                Dfs(c, v);                 // tính xong cây con của c\n                sz[v] += sz[c];            // rồi gộp vào v\n            }\n    }\n\n    static void Main()\n    {\n        DocCay();\n        sz = new int[n + 1];\n        Dfs(1, 0);\n        for (int v = 1; v <= n; v++) Console.Write(sz[v] + \" \");\n        Console.WriteLine();\n    }\n}"}},{label:"Ví dụ: Bữa tiệc công ty",input:"9\n1 2\n1 3\n2 4\n2 5\n3 6\n5 7\n5 8\n6 9\n3 5 4 2 6 1 7 3 8\n",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n;\nvector<vector<int>> adj;\n\nvoid docCay() {\n    cin >> n;\n    adj.resize(n + 1);\n    for (int i = 0; i < n - 1; i++) {\n        int a, b;\n        cin >> a >> b;\n        adj[a].push_back(b);\n        adj[b].push_back(a);\n    }\n}\n\nvector<int> cha, thuTu;\n\nvoid bfs(int goc) {                    // thứ tự BFS: cha luôn đứng trước con\n    cha.assign(n + 1, 0);\n    thuTu = {goc};\n    cha[goc] = -1;\n    for (int i = 0; i < (int)thuTu.size(); i++) {\n        int u = thuTu[i];\n        for (int v : adj[u])\n            if (v != cha[u]) { cha[v] = u; thuTu.push_back(v); }\n    }\n}\n\nint main() {\n    docCay();\n    vector<long long> w(n + 1);\n    for (int v = 1; v <= n; v++) cin >> w[v];   // độ vui của từng người\n    bfs(1);\n    vector<long long> moi(n + 1, 0), khong(n + 1, 0);   // dp[v][1], dp[v][0]\n    for (int i = n - 1; i >= 0; i--) { // duyệt ngược BFS: con trước, cha sau\n        int v = thuTu[i];\n        moi[v] = w[v];\n        for (int c : adj[v])\n            if (c != cha[v]) {\n                moi[v] += khong[c];                 // mời v: con không được mời\n                khong[v] += max(moi[c], khong[c]);  // không mời v: con tùy ý\n            }\n    }\n    cout << max(moi[1], khong[1]) << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",base:1,xy:[[0.5,0],[0.25,0.33],[0.75,0.33],[0.08,0.66],[0.4,0.66],[0.75,0.66],[0.28,1],[0.52,1],[0.75,1]],adj:"adj",par:"cha",lab:"moi",cur:["v","c"]},{type:"cells",of:"khong",ptr:["v"]}],py:{code:"n = int(input())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(n - 1):\n    a, b = map(int, input().split())\n    adj[a].append(b)\n    adj[b].append(a)\n\ndef bfs(goc):                          # thứ tự BFS: cha luôn đứng trước con\n    cha = [0] * (n + 1)\n    cha[goc] = -1\n    thu_tu = [goc]\n    for u in thu_tu:\n        for v in adj[u]:\n            if v != cha[u]:\n                cha[v] = u\n                thu_tu.append(v)\n    return cha, thu_tu\n\nw = [0] + list(map(int, input().split()))   # độ vui của từng người\ncha, thu_tu = bfs(1)\nmoi = [0] * (n + 1)                    # dp[v][1]\nkhong = [0] * (n + 1)                  # dp[v][0]\nfor v in reversed(thu_tu):             # duyệt ngược BFS: con trước, cha sau\n    moi[v] = w[v]\n    for c in adj[v]:\n        if c != cha[v]:\n            moi[v] += khong[c]                  # mời v: con không được mời\n            khong[v] += max(moi[c], khong[c])   # không mời v: con tùy ý\nprint(max(moi[1], khong[1]))"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static int n;\n    static List<int>[] adj;\n\n    static void DocCay()\n    {\n        n = int.Parse(Console.ReadLine());\n        adj = new List<int>[n + 1];\n        for (int i = 0; i <= n; i++) adj[i] = new List<int>();\n        for (int i = 0; i < n - 1; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            adj[e[1]].Add(e[0]);\n        }\n    }\n\n    static int[] cha;\n    static List<int> thuTu;\n\n    static void Bfs(int goc)               // thứ tự BFS: cha luôn đứng trước con\n    {\n        cha = new int[n + 1];\n        cha[goc] = -1;\n        thuTu = new List<int> { goc };\n        for (int i = 0; i < thuTu.Count; i++)\n        {\n            int u = thuTu[i];\n            foreach (int v in adj[u])\n                if (v != cha[u]) { cha[v] = u; thuTu.Add(v); }\n        }\n    }\n\n    static void Main()\n    {\n        DocCay();\n        long[] w = Array.ConvertAll((\"0 \" + Console.ReadLine()).Split(), long.Parse);   // độ vui của từng người\n        Bfs(1);\n        long[] moi = new long[n + 1], khong = new long[n + 1];   // dp[v][1], dp[v][0]\n        for (int i = n - 1; i >= 0; i--)       // duyệt ngược BFS: con trước, cha sau\n        {\n            int v = thuTu[i];\n            moi[v] = w[v];\n            foreach (int c in adj[v])\n                if (c != cha[v])\n                {\n                    moi[v] += khong[c];                     // mời v: con không được mời\n                    khong[v] += Math.Max(moi[c], khong[c]); // không mời v: con tùy ý\n                }\n        }\n        Console.WriteLine(Math.Max(moi[1], khong[1]));\n    }\n}"}},{label:"Ví dụ: Đường kính cây",input:"9\n1 2\n1 3\n2 4\n2 5\n3 6\n5 7\n5 8\n6 9\n",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n;\nvector<vector<int>> adj;\n\nvoid docCay() {\n    cin >> n;\n    adj.resize(n + 1);\n    for (int i = 0; i < n - 1; i++) {\n        int a, b;\n        cin >> a >> b;\n        adj[a].push_back(b);\n        adj[b].push_back(a);\n    }\n}\n\nint kq = 0;\n\nint dfs(int v, int p) {                // trả về đường đi xuống dài nhất từ v\n    int a = 0, b = 0;                  // hai nhánh dài nhất\n    for (int c : adj[v])\n        if (c != p) {\n            int d = dfs(c, v) + 1;\n            if (d > a) { b = a; a = d; }\n            else if (d > b) b = d;\n        }\n    kq = max(kq, a + b);               // đường đi “gập” tại v\n    return a;\n}\n\nint main() {\n    docCay();\n    dfs(1, 0);\n    cout << kq << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",base:1,xy:[[0.5,0],[0.25,0.33],[0.75,0.33],[0.08,0.66],[0.4,0.66],[0.75,0.66],[0.28,1],[0.52,1],[0.75,1]],adj:"adj",cur:["v","c"]},{type:"calls"}],py:{code:"def dfs(v, p):                         # trả về đường đi xuống dài nhất từ v\n    global kq\n    a = b = 0                          # hai nhánh dài nhất\n    for c in adj[v]:\n        if c != p:\n            d = dfs(c, v) + 1\n            if d > a:\n                a, b = d, a\n            elif d > b:\n                b = d\n    kq = max(kq, a + b)                # đường đi “gập” tại v\n    return a\n\nn = int(input())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(n - 1):\n    a, b = map(int, input().split())\n    adj[a].append(b)\n    adj[b].append(a)\nkq = 0\ndfs(1, 0)\nprint(kq)"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static int n;\n    static List<int>[] adj;\n\n    static void DocCay()\n    {\n        n = int.Parse(Console.ReadLine());\n        adj = new List<int>[n + 1];\n        for (int i = 0; i <= n; i++) adj[i] = new List<int>();\n        for (int i = 0; i < n - 1; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            adj[e[1]].Add(e[0]);\n        }\n    }\n\n    static int kq = 0;\n\n    static int Dfs(int v, int p)           // trả về đường đi xuống dài nhất từ v\n    {\n        int a = 0, b = 0;                  // hai nhánh dài nhất\n        foreach (int c in adj[v])\n            if (c != p)\n            {\n                int d = Dfs(c, v) + 1;\n                if (d > a) { b = a; a = d; }\n                else if (d > b) b = d;\n            }\n        kq = Math.Max(kq, a + b);          // đường đi “gập” tại v\n        return a;\n    }\n\n    static void Main()\n    {\n        DocCay();\n        Dfs(1, 0);\n        Console.WriteLine(kq);\n    }\n}"}},{label:"Ví dụ: Đổi gốc — tổng khoảng cách",input:"9\n1 2\n1 3\n2 4\n2 5\n3 6\n5 7\n5 8\n6 9\n",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n;\nvector<vector<int>> adj;\n\nvoid docCay() {\n    cin >> n;\n    adj.resize(n + 1);\n    for (int i = 0; i < n - 1; i++) {\n        int a, b;\n        cin >> a >> b;\n        adj[a].push_back(b);\n        adj[b].push_back(a);\n    }\n}\n\nvector<int> cha, thuTu;\n\nvoid bfs(int goc) {                    // thứ tự BFS: cha luôn đứng trước con\n    cha.assign(n + 1, 0);\n    thuTu = {goc};\n    cha[goc] = -1;\n    for (int i = 0; i < (int)thuTu.size(); i++) {\n        int u = thuTu[i];\n        for (int v : adj[u])\n            if (v != cha[u]) { cha[v] = u; thuTu.push_back(v); }\n    }\n}\n\nint main() {\n    docCay();\n    bfs(1);\n    vector<long long> sz(n + 1, 1), kq(n + 1, 0), sau(n + 1, 0);\n    for (int i = 1; i < n; i++) sau[thuTu[i]] = sau[cha[thuTu[i]]] + 1;\n    for (int i = n - 1; i > 0; i--) sz[cha[thuTu[i]]] += sz[thuTu[i]];   // con trước, cha sau\n    for (int v = 1; v <= n; v++) kq[1] += sau[v];   // gốc 1: tổng độ sâu\n    for (int i = 1; i < n; i++) {      // cha trước, con sau\n        int c = thuTu[i];\n        kq[c] = kq[cha[c]] - sz[c] + (n - sz[c]);\n    }\n    for (int v = 1; v <= n; v++) cout << kq[v] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",base:1,xy:[[0.5,0],[0.25,0.33],[0.75,0.33],[0.08,0.66],[0.4,0.66],[0.75,0.66],[0.28,1],[0.52,1],[0.75,1]],adj:"adj",par:"cha",lab:"kq",cur:["c"]},{type:"cells",of:"sz",ptr:["c"]}],py:{code:"n = int(input())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(n - 1):\n    a, b = map(int, input().split())\n    adj[a].append(b)\n    adj[b].append(a)\n\ndef bfs(goc):                          # thứ tự BFS: cha luôn đứng trước con\n    cha = [0] * (n + 1)\n    cha[goc] = -1\n    thu_tu = [goc]\n    for u in thu_tu:\n        for v in adj[u]:\n            if v != cha[u]:\n                cha[v] = u\n                thu_tu.append(v)\n    return cha, thu_tu\n\ncha, thu_tu = bfs(1)\nsz = [1] * (n + 1)\nsau = [0] * (n + 1)\nfor v in thu_tu[1:]:\n    sau[v] = sau[cha[v]] + 1\nfor v in reversed(thu_tu[1:]):         # con trước, cha sau\n    sz[cha[v]] += sz[v]\nkq = [0] * (n + 1)\nkq[1] = sum(sau)                       # gốc 1: tổng độ sâu\nfor c in thu_tu[1:]:                   # cha trước, con sau\n    kq[c] = kq[cha[c]] - sz[c] + (n - sz[c])\nprint(*kq[1:])"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static int n;\n    static List<int>[] adj;\n\n    static void DocCay()\n    {\n        n = int.Parse(Console.ReadLine());\n        adj = new List<int>[n + 1];\n        for (int i = 0; i <= n; i++) adj[i] = new List<int>();\n        for (int i = 0; i < n - 1; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            adj[e[1]].Add(e[0]);\n        }\n    }\n\n    static int[] cha;\n    static List<int> thuTu;\n\n    static void Bfs(int goc)               // thứ tự BFS: cha luôn đứng trước con\n    {\n        cha = new int[n + 1];\n        cha[goc] = -1;\n        thuTu = new List<int> { goc };\n        for (int i = 0; i < thuTu.Count; i++)\n        {\n            int u = thuTu[i];\n            foreach (int v in adj[u])\n                if (v != cha[u]) { cha[v] = u; thuTu.Add(v); }\n        }\n    }\n\n    static void Main()\n    {\n        DocCay();\n        Bfs(1);\n        long[] sz = new long[n + 1], kq = new long[n + 1], sau = new long[n + 1];\n        for (int v = 1; v <= n; v++) sz[v] = 1;\n        for (int i = 1; i < n; i++) sau[thuTu[i]] = sau[cha[thuTu[i]]] + 1;\n        for (int i = n - 1; i > 0; i--) sz[cha[thuTu[i]]] += sz[thuTu[i]];   // con trước, cha sau\n        for (int v = 1; v <= n; v++) kq[1] += sau[v];   // gốc 1: tổng độ sâu\n        for (int i = 1; i < n; i++)            // cha trước, con sau\n        {\n            int c = thuTu[i];\n            kq[c] = kq[cha[c]] - sz[c] + (n - sz[c]);\n        }\n        for (int v = 1; v <= n; v++) Console.Write(kq[v] + \" \");\n        Console.WriteLine();\n    }\n}"}},{label:"Lỗi: đệ quy quá sâu trên cây dạng đường thẳng",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n = 1000000;                       // cây đường thẳng 1 – 2 – 3 – … – n\n\nint kichThuoc(int v) {                 // con duy nhất của v là v + 1\n    if (v == n) return 1;\n    return 1 + kichThuoc(v + 1);       // độ sâu đệ quy n\n}\n\nint main() {\n    cout << kichThuoc(1) << \"\\n\";\n    return 0;\n}",viz:[{type:"calls"}],py:{code:"n = 1000000                            # cây đường thẳng 1 – 2 – 3 – … – n\n\ndef kich_thuoc(v):                     # con duy nhất của v là v + 1\n    if v == n:\n        return 1\n    return 1 + kich_thuoc(v + 1)       # độ sâu đệ quy n\n\nprint(kich_thuoc(1))",note:"Python mặc định chỉ cho đệ quy sâu khoảng 1000 tầng: RecursionError. Tăng sys.setrecursionlimit có thể làm tràn ngăn xếp thật của tiến trình. Với cây lớn, dùng thứ tự BFS ngược như các ví dụ trên."},cs:{code:"using System;\n\nclass Program\n{\n    static int n = 1000000;                // cây đường thẳng 1 – 2 – 3 – … – n\n\n    static int KichThuoc(int v)            // con duy nhất của v là v + 1\n    {\n        if (v == n) return 1;\n        return 1 + KichThuoc(v + 1);       // độ sâu đệ quy n\n    }\n\n    static void Main()\n    {\n        Console.WriteLine(KichThuoc(1));\n    }\n}",note:"Một triệu lời gọi lồng nhau vượt ngăn xếp mặc định (khoảng 1 MB) của .NET: StackOverflowException, tiến trình bị dừng ngay. Trình mô phỏng dừng ở độ sâu 5000. Với cây lớn, dùng thứ tự BFS ngược như các ví dụ trên."}}];
